$(function () {
  // Admin Panel settings
  "use strict";

  // Check for and apply saved sidebar state
  const savedSidebarState = localStorage.getItem("sidebarState");
  const mainWrapper = $("#main-wrapper");

  /**
   * This function sets the sidebar type based on window width.
   */
  const setSidebarType = function () {
    const width = window.innerWidth > 0 ? window.innerWidth : this.screen.width;
    if (width < 1199) {
      mainWrapper.attr("data-sidebartype", "mini-sidebar");
      mainWrapper.addClass("mini-sidebar");
    } else {
      if (savedSidebarState === "mini") {
        mainWrapper.attr("data-sidebartype", "mini-sidebar");
        mainWrapper.addClass("mini-sidebar");
        $(".sidebartoggler").prop("checked", true);
      } else {
        mainWrapper.attr("data-sidebartype", "full");
        mainWrapper.removeClass("mini-sidebar");
        $(".sidebartoggler").prop("checked", false);
      }
    }
  };

  // Run on page load
  setSidebarType();
  $(window).on("resize", setSidebarType);

  /**
   * This is for the sidebar toggler
   */
  $(".sidebartoggler").on("click", function () {
    mainWrapper.toggleClass("mini-sidebar show-sidebar");

    if (mainWrapper.hasClass("mini-sidebar")) {
      $(".sidebartoggler").prop("checked", true);
      mainWrapper.attr("data-sidebartype", "mini-sidebar");
      localStorage.setItem("sidebarState", "mini");
    } else {
      $(".sidebartoggler").prop("checked", false);
      mainWrapper.attr("data-sidebartype", "full");
      localStorage.setItem("sidebarState", "full");
    }
  });

  // =================================================
  // Dark Mode Toggle
  // =================================================
  const body = $("body");
  const darkModeToggle = $("#dark-mode-toggle"); // The ID from the HTML in Step 1

  // Check for saved theme preference on page load
  const savedTheme = localStorage.getItem("theme");
  if (savedTheme === "dark") {
    body.addClass("dark-mode");
    darkModeToggle.prop("checked", true);
  }

  // Add click handler for the toggle
  darkModeToggle.on("click", function () {
    body.toggleClass("dark-mode");
    const theme = body.hasClass("dark-mode") ? "dark" : "light";
    localStorage.setItem("theme", theme);
  });
});